bel>\n            <label\n              v-if=\"hasPrefix\"\n              class=\"flex cursor-pointer items-center gap-1 rounded border border-(--quick-send-border-color) bg-(--quick-send-bg-sec) px-2 py-1 transition-colors hover:bg-(--quick-send-bg-sec)/70\"\n            >\n              <Checkbox\n                :model-value=\"importSelection.prefix\"\n                input-id=\"import-prefix\"\n                binary\n                @update:model-value=\"updateImportFlag('prefix', $event)\"\n              />\n              <span class=\"kk-text-sm\">前缀列表</span>\n            </label>\n            <label\n              v-if=\"hasSuffix\"\n              class=\"flex cursor-pointer items-center gap-1 rounded border border-(--quick-send-border-color) bg-(--quick-send-bg-sec) px-2 py-1 transition-colors hover:bg-(--quick-send-bg-sec)/70\"\n            >\n              <Checkbox\n                :model-value=\"importSelection.suffix\"\n                input-id=\"import-suffix\"\n                binary\n                @update:model-value=\"updateImportFlag('suffix', $event)\"\n              />\n              <span class=\"kk-text-sm\">后缀列表</span>\n            </label>\n          </div>\n        </section>\n\n        <!-- 导入模式 -->\n        <section v-if=\"importFile\" class=\"flex flex-col gap-1\">\n          <div class=\"kk-text-sm flex items-center gap-0.5 font-semibold text-(--quick-send-text)/70\">\n            <span class=\"icon-[flowbite--merge-cells-outline]\"></span>\n            <span>导入模式</span>\n          </div>\n          <div class=\"flex flex-col gap-1\">\n            <label\n              class=\"flex cursor-pointer items-start gap-1 rounded border-2 bg-(--quick-send-bg-sec) px-2 py-1 transition-colors\"\n              :class=\"\n                importMode === 'overwrite'\n                  ? 'border-(--quick-send-primary-color) bg-(--quick-send-primary-color)/10'\n                  : 'border-(--quick-send-border-color) opacity-70 hover:opacity-100'\n   