 </template>\n    </div>\n\n    <template #footer>\n      <div class=\"flex justify-end gap-1\">\n        <Button label=\"取消\" size=\"small\" text @click=\"closeModal\" />\n        <Button v-if=\"activeTab === 0\" label=\"确认导出\" size=\"small\" @click=\"confirmExport\" />\n        <Button v-else label=\"确认导入\" size=\"small\" :disabled=\"!importFile\" @click=\"confirmImport\" />\n      </div>\n    </template>\n  </Dialog>\n</template>\n\n<script lang=\"ts\" setup>\nimport Button from 'primevue/button';\nimport Checkbox from 'primevue/checkbox';\nimport Dialog from 'primevue/dialog';\nimport RadioButton from 'primevue/radiobutton';\nimport SelectButton from 'primevue/selectbutton';\nimport Tree from 'primevue/tree';\nimport { computed, ref, watch } from 'vue';\nimport type { ExportFile, ExportSelection, ImportMode, ImportSelection } from '../types';\n\n/** 树节点类型（用于 PrimeVue Tree 组件） */\ninterface TreeNode {\n  key: string;\n  label?: string;\n  children?: TreeNode[];\n  leaf?: boolean;\n  path?: (string | number)[];\n}\n\ntype TreeSelectionKey = { checked?: boolean; partialChecked?: boolean };\ntype TreeSelectionKeys = Record<string, TreeSelectionKey>;\n\nconst props = defineProps<{\n  visible: boolean;\n  activeTab: number;\n  exportSelection: ExportSelection;\n  importMode: ImportMode;\n  importSelection: ImportSelection;\n  importFile: ExportFile | null;\n  dataTree: TreeNode[];\n  fileInfo: { name: string; size: string; exportTime: string };\n  hasData: boolean;\n  hasPrefix: boolean;\n  hasSuffix: boolean;\n}>();\n\nconst emit = defineEmits<{\n  (e: 'update:visible', value: boolean): void;\n  (e: 'update:activeTab', value: number): void;\n  (e: 'update:exportSelection', value: ExportSelection): void;\n  (e: 'update:importMode', value: ImportMode): void;\n  (e: 'update:importSelection', value: ImportSelection): void;\n  (e: 'expand-data-node', value: TreeNode): void;\n  (e: 'confirm-export'): void;\n  (e: 'select-file'): void;\n  (e: 'confirm-import'): void;\n}>();