const SMART_THEME_QUOTE_COLOR = '--SmartThemeQuoteColor';
const MAIN_FONT_SIZE_VARIABLE = '--mainFontSize';
const DEFAULT_BASE_FONT_SIZE = 15;

export type ThemeColors = {
  primaryColor?: string;
};

/**
 * 从父页面获取 CSS 变量值
 */
export function getParentThemeVariable(variableName: string): string | undefined {
  try {
    const parentRoot = window.parent.document.documentElement;
    const parentStyles = window.parent.getComputedStyle(parentRoot);
    const cssVarValue = parentStyles.getPropertyValue(variableName).trim();
    return cssVarValue || undefined;
  } catch (error) {
    console.warn('读取父页面主题变量失败', error);
    return undefined;
  }
}

/**
 * 移除颜色值中的 alpha 通道，支持多种颜色格式
 */
export function removeColorAlpha(color: string | undefined): string | undefined {
  if (!color) return undefined;
  const trimmed = color.trim();

  const oldStyleMatch = trimmed.match(/^rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*[\d.]+\s*\)$/i);
  if (oldStyleMatch) {
    return `rgb(${oldStyleMatch[1]}, ${oldStyleMatch[2]}, ${oldStyleMatch[3]})`;
  }

  const newStyleMatch = trimmed.match(/^rgba?\(\s*(\d+)\s+(\d+)\s+(\d+)\s*\/\s*[\d.]+\s*\)$/i);
  if (newStyleMatch) {
    return `rgb(${newStyleMatch[1]}, ${newStyleMatch[2]}, ${newStyleMatch[3]})`;
  }

  const hexAlphaMatch = trimmed.match(/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})[0-9a-f]{2}$/i);
  if (hexAlphaMatch) {
    const r = parseInt(hexAlphaMatch[1], 16);
    const g = parseInt(hexAlphaMatch[2], 16);
    const b = parseInt(hexAlphaMatch[3], 16);
    return `rgb(${r}, ${g}, ${b})`;
  }

  return trimmed;
}

/**
 * 获取父页面的主题颜色配置
 */
export function getThemeColors(): ThemeColors {
  return {
    primaryColor: removeColorAlpha(getParentThemeVariable(SMART_THEME_QUOTE_COLOR)),
  };
}

/**
 * 将父页面引用色同步到当前文档
 */
export function syncStColorTheme(target: CSSStyleDeclaration = document.documentElement.style): void {
  try {
    const value = getThemeColors().primaryColor;
    if (value) {
      target.setProperty(SMART_THEME_QUOTE_COLOR, value);
    }
  } catch (error) {
    console.warn('同步父页面引用色失败', error);
  }
}

/**
 * 获取父页面字体缩放对应的 iframe 默认根字号
 */
export function getParentIframeRootFontSize(baseFontSize: number = DEFAULT_BASE_FONT_SIZE): number {
  const parentWindow = window.parent as typeof window.parent & { $?: JQueryStatic };
  const fontScaleCounter = parentWindow.$?.('#font_scale_counter');
  const ratio = (fontScaleCounter?.val() as number | string | undefined) || 1;
  const numericRatio = typeof ratio === 'string' ? Number(ratio) : ratio;
  return baseFontSize * (Number.isFinite(numericRatio) ? numericRatio : 1);
}

/**
 * 将指定根字号应用到当前 iframe
 */
export function applyIframeRootFontSize(fontSize: number, target: CSSStyleDeclaration = document.documentElement.style): void {
  const fontSizeValue = `${fontSize}px`;
  target.fontSize = fontSizeValue;
  target.setProperty(MAIN_FONT_SIZE_VARIABLE, fontSizeValue);
}

/**
 * 兼容旧入口：使用父页面字号作为当前 iframe 根字号
 */
export function syncIframeRootRemFromParentMainFontSize(baseFontSize: number = DEFAULT_BASE_FONT_SIZE): void {
  applyIframeRootFontSize(getParentIframeRootFontSize(baseFontSize));
}

/**
 * 脚本类项目通用：一键同步 ST 主题变量
 */
export function syncScriptProjectTheme(): void {
  syncStColorTheme();
}
