import type { RawData, ExportData, ExportSelection, ExportFile } from '../types';

type FilterResult = { included: boolean; value?: unknown };

/**
 * 根据选择状态生成导出数据
 */
export function buildExportData(rawData: RawData, selection: ExportSelection): ExportData {
  const result: ExportData = {};

  if (selection.data.selectedPaths.size > 0) {
    result.data = filterDataBySelection(rawData.data, selection.data.selectedPaths);
  }

  if (selection.prefix) {
    result.prefix = rawData.prefix ?? rawData.perfix ?? [];
  }

  if (selection.suffix) {
    result.suffix = rawData.suffix ?? [];
  }

  return result;
}

/**
 * 根据选中的路径过滤快捷指令数据
 */
export function filterDataBySelection(data: unknown[], selectedPaths: Set<string>): unknown[] {
  const result: unknown[] = [];

  data.forEach((item, index) => {
    const filtered = filterNodeBySelection(item, [index], selectedPaths);
    if (filtered.included) result.push(filtered.value);
  });

  return result;
}

/**
 * 格式化导出选择路径
 */
export function formatExportPathKey(path: (string | number)[]): string {
  const body = path.map(segment => (typeof segment === 'string' ? JSON.stringify(segment) : segment)).join(',');
  return `[${body}]`;
}

/**
 * 根据路径过滤单个节点
 */
function filterNodeBySelection(value: unknown, path: (string | number)[], selectedPaths: Set<string>): FilterResult {
  if (selectedPaths.has(formatExportPathKey(path))) {
    return { included: true, value };
  }
  if (Array.isArray(value)) return filterArrayBySelection(value, path, selectedPaths);
  if (isPlainObject(value)) return filterObjectBySelection(value, path, selectedPaths);
  return { included: false };
}

/**
 * 过滤数组类型的条目
 */
function filterArrayBySelection(value: unknown[], path: (string | number)[], selectedPaths: Set<string>): FilterResult {
  const grid = getGridChildren(value);
  if (grid) return filterGridTuple(value, path, grid, selectedPaths);

  const children = filterArrayChildren(value, path, selectedPaths);
  return { included: children.length > 0, value: children };
}

/**
 * 过滤快捷指令 grid 元组
 */
function filterGridTuple(
  value: unknown[],
  path: (string | number)[],
  grid: { index: number; children: unknown[] },
  selectedPaths: Set<string>,
): FilterResult {
  const children = filterArrayChildren(grid.children, [...path, grid.index], selectedPaths);
  if (children.length === 0) return { included: false };

  const result = [...value];
  result[grid.index] = children;
  return { included: true, value: result };
}

/**
 * 过滤数组子项
 */
function filterArrayChildren(value: unknown[], path: (string | number)[], selectedPaths: Set<string>): unknown[] {
  return value.flatMap((item, index) => {
    const filtered = filterNodeBySelection(item, [...path, index], selectedPaths);
    return filtered.included ? [filtered.value] : [];
  });
}

/**
 * 过滤对象类型的条目
 */
function filterObjectBySelection(
  value: Record<string, unknown>,
  path: (string | number)[],
  selectedPaths: Set<string>,
): FilterResult {
  const result: Record<string, unknown> = {};

  Object.entries(value).forEach(([key, child]) => {
    const filtered = filterNodeBySelection(child, [...path, key], selectedPaths);
    if (filtered.included) result[key] = filtered.value;
  });

  return { included: Object.keys(result).length > 0, value: result };
}

/**
 * 生成导出文件对象
 */
export function createExportFile(data: ExportData): ExportFile {
  return {
    exportTime: new Date().toISOString(),
    data,
  };
}

/**
 * 触发浏览器下载 JSON 文件
 */
export function downloadJSON(file: ExportFile, filename: string): void {
  const json = JSON.stringify(file, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  URL.revokeObjectURL(url);
}

/**
 * 生成导出文件名
 */
export function generateExportFilename(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hour = String(now.getHours()).padStart(2, '0');
  const minute = String(now.getMinutes()).padStart(2, '0');
  const second = String(now.getSeconds()).padStart(2, '0');

  return `quicksend-export-${year}${month}${day}-${hour}${minute}${second}.json`;
}

/**
 * 判断是否为普通对象
 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}

/**
 * 读取快捷指令 grid 子数组
 */
function getGridChildren(value: unknown[]): { index: number; children: unknown[] } | null {
  if (Array.isArray(value[1])) return { index: 1, children: value[1] };
  return null;
}
