import { useLocalStorage } from '@vueuse/core';
import { onUnmounted, ref, watch, type Ref } from 'vue';
import { applyIframeRootFontSize, getParentIframeRootFontSize } from '@util/common/theme';
import type { RawData } from '../types';

/** 快捷指令面板主题模式 */
export type QuickSendThemeMode = 'light' | 'dark';

const DEFAULT_THEME_MODE: QuickSendThemeMode = 'light';
const DARK_MODE_CLASS = 'quick-send-dark';
const MIN_ROOT_FONT_SIZE = 12;
const MAX_ROOT_FONT_SIZE = 24;

/** 判断值是否为合法的主题模式 */
function isThemeMode(value: unknown): value is QuickSendThemeMode {
  return value === 'light' || value === 'dark';
}

/** 切换 document.documentElement 的暗色模式类 */
function applyThemeMode(mode: QuickSendThemeMode): void {
  document.documentElement.classList.toggle(DARK_MODE_CLASS, mode === 'dark');
}

/** 规范化根字号：取最近 0.5px，并夹在 [MIN, MAX] 区间 */
function normalizeRootFontSize(value: unknown, fallback: number = getParentIframeRootFontSize()): number {
  const numericValue = typeof value === 'number' ? value : Number(value);
  const fontSize = Number.isFinite(numericValue) ? numericValue : fallback;
  return Math.min(MAX_ROOT_FONT_SIZE, Math.max(MIN_ROOT_FONT_SIZE, Math.round(fontSize * 2) / 2));
}

/** 应用根字号到 iframe */
function applyRootFontSize(fontSize: number): void {
  applyIframeRootFontSize(normalizeRootFontSize(fontSize));
}

/**
 * 快捷指令面板主题管理 composable
 * 接收 rawData 作为参数，管理 themeMode / rootFontSize localStorage 同步与副作用应用
 */
export function useTheme(rawData: RawData): {
  themeMode: Ref<QuickSendThemeMode>;
  rootFontSize: Ref<number>;
  settingsOpen: Ref<boolean>;
  openSettings: () => void;
} {
  const settingsOpen = ref(false);

  const themeMode = useLocalStorage<QuickSendThemeMode>(
    'quicksend:themeMode',
    isThemeMode(rawData.themeMode) ? rawData.themeMode : DEFAULT_THEME_MODE,
  );
  const rootFontSize = useLocalStorage<number>('quicksend:rootFontSize', normalizeRootFontSize(rawData.rootFontSize));

  watch(
    themeMode,
    mode => {
      if (!isThemeMode(mode)) {
        themeMode.value = DEFAULT_THEME_MODE;
        return;
      }
      applyThemeMode(mode);
    },
    { immediate: true },
  );

  watch(
    rootFontSize,
    fontSize => {
      const normalizedFontSize = normalizeRootFontSize(fontSize);
      if (rootFontSize.value !== normalizedFontSize) {
        rootFontSize.value = normalizedFontSize;
        return;
      }
      applyRootFontSize(normalizedFontSize);
    },
    { immediate: true },
  );

  onUnmounted(() => {
    document.documentElement.classList.remove(DARK_MODE_CLASS);
  });

  /** 打开主题设置弹窗 */
  function openSettings(): void {
    settingsOpen.value = true;
  }

  return { themeMode, rootFontSize, settingsOpen, openSettings };
}
