import { getThemeColors } from '@util/common/theme';

/** 默认引用色 */
const DEFAULT_QUOTE_COLOR = '#4a9eff';

/**
 * 将父页面引用色注入到 iframe :root
 * 仅在 start() 时调用一次，失败时降级为默认主题
 */
export function injectThemeCssVariables(): void {
  const root = document.documentElement;
  try {
    const colors = getThemeColors();
    root.style.setProperty('--SmartThemeQuoteColor', colors.primaryColor ?? DEFAULT_QUOTE_COLOR);
  } catch (error) {
    console.error('[快捷指令面板] 引用色同步失败，使用默认主题', error);
    root.style.setProperty('--SmartThemeQuoteColor', DEFAULT_QUOTE_COLOR);
  }
}
