import { reactive, toRef, type Ref } from 'vue';
import type { RawData } from '../types';
import { persistRawData as persistRawDataUtil } from '../utils/persist';

const { getVariables, getScriptId } = window;

/** 默认弹窗尺寸（与 ThemeSettingsModal 中保持一致） */
const DEFAULT_POPUP_SIZE = {
  desktop: { width: '50dvw', height: '60dvh' },
  mobile: { width: '90dvw', height: '80dvh' },
} as const;

/** 默认替换词配置 */
const DEFAULT_REPLACE_NAMES = { user: ['user'], char: ['character(s)'] } as const;

/** 初始化 rawData.data：保证为数组，并在变更时持久化 */
function ensureDataArray(rawData: RawData): void {
  if (Array.isArray(rawData.data)) return;
  rawData.data = [];
  persistRawDataUtil(rawData);
}

/** 初始化 rawData.popupSize：缺失时写入默认尺寸 */
function ensurePopupSize(rawData: RawData): void {
  if (rawData.popupSize != null && typeof rawData.popupSize === 'object') return;
  rawData.popupSize = { desktop: { ...DEFAULT_POPUP_SIZE.desktop }, mobile: { ...DEFAULT_POPUP_SIZE.mobile } };
  persistRawDataUtil(rawData);
}

/** 判断 replaceNames 是否结构合法 */
function isReplaceNamesValid(rn: RawData['replaceNames']): boolean {
  return (
    rn != null && typeof rn === 'object' && typeof rn.user === 'object' && typeof rn.char === 'object' && rn.user != null
  );
}

/** 初始化 rawData.replaceNames：缺失或类型错误时写入默认值，并兜底转为数组 */
function ensureReplaceNames(rawData: RawData): void {
  if (!isReplaceNamesValid(rawData.replaceNames)) {
    rawData.replaceNames = { user: [...DEFAULT_REPLACE_NAMES.user], char: [...DEFAULT_REPLACE_NAMES.char] };
    persistRawDataUtil(rawData);
  }
  const rn = rawData.replaceNames!;
  if (!Array.isArray(rn.user)) rn.user = Array.from(rn.user ?? []);
  if (!Array.isArray(rn.char)) rn.char = Array.from(rn.char ?? []);
}

/**
 * 快捷指令面板数据根 composable
 * 单一所有者：创建唯一的 rawData reactive proxy，
 * 其它 composables 通过参数接收，避免多 reactive 副本写入不同步
 */
export function useQuickSendData(): {
  rawData: RawData;
  quickSendData: Ref<unknown[]>;
  persistRawData: () => void;
} {
  const rawData = reactive(getVariables({ type: 'script', script_id: getScriptId() }) as RawData);
  ensureDataArray(rawData);
  ensurePopupSize(rawData);
  ensureReplaceNames(rawData);

  // quickSendData：toRef 使其可直接修改，便于 useSortable 工作
  const quickSendData = toRef(rawData, 'data');

  /** 持久化 rawData 到脚本变量（包装 utils/persist.ts） */
  const persistRawData = (): void => persistRawDataUtil(rawData);

  return { rawData, quickSendData, persistRawData };
}
