import { createApp, type App } from 'vue';
import './index.css';
import AppComponent from './index.vue';
import { applyIframeRootFontSize, getParentIframeRootFontSize, getThemeColors } from '@util/common/theme';
import { injectThemeCssVariables } from './utils/theme';
import PrimeVue from 'primevue/config';
import Tooltip from 'primevue/tooltip';
import { createCustomPreset } from '../shared/utils/themePreset';

let app: App | null = null;
let appRoot: HTMLElement | null = null;

function bindButtonEvent() {
  const buttonName = getScriptButtons()[0]?.name;
  if (buttonName) {
    console.log('【快捷指令面板】找到触发按钮:', buttonName);
    const event_type = getButtonEvent(buttonName);
    eventOn(event_type, () => {
      start();
    });
  } else {
    console.error('没有找到按钮');
  }
}

$(() => {
  bindButtonEvent();
});

/**
 * 启动快捷指令面板
 * 同步字体与主题 → 设置 iframe 样式 → 挂载 Vue 应用
 */
export function start() {
  // 幂等处理：先清理旧实例
  cleanup();

  try {
    applyIframeRootFontSize(getParentIframeRootFontSize());
    injectThemeCssVariables();

    document.documentElement.style.overflow = 'hidden';
    document.body.style.margin = '0';

    const frameEl = window.frameElement as HTMLIFrameElement | null;
    if (frameEl) {
      frameEl.style.position = 'fixed';
      frameEl.style.top = '0';
      frameEl.style.left = '0';
      frameEl.style.width = '100dvw';
      frameEl.style.height = '100dvh';
      frameEl.style.zIndex = '10000';
      frameEl.style.border = 'none';
      frameEl.style.display = 'block';
    } else {
      console.error('[快捷指令面板] 无法访问 iframe 元素');
    }

    appRoot = document.createElement('div');
    appRoot.id = 'app-root';
    appRoot.style.height = '100dvh';
    appRoot.style.width = '100dvw';
    appRoot.style.display = 'flex';
    appRoot.style.justifyContent = 'center';
    appRoot.style.alignItems = 'center';
    document.body.appendChild(appRoot);

    app = createApp(AppComponent);
    app.provide('onClose', cleanup);
    app.use(PrimeVue, {
      license: __PRIMEUI_LICENSE__,
      theme: {
        preset: createCustomPreset(getThemeColors()),
        options: { darkModeSelector: '.quick-send-dark' },
      },
      zIndex: {
        modal: 10100,
        overlay: 10000,
        menu: 10000,
        tooltip: 10200,
      },
    });
    app.directive('tooltip', Tooltip);
    app.mount(appRoot);
    console.info('【快捷指令面板】已启动');
  } catch (error) {
    console.error('[快捷指令面板] 启动失败', error);
    cleanup();
  }
}

/**
 * 清理快捷指令面板资源（幂等，可重复调用）
 */
export function cleanup() {
  try {
    if (app) {
      app.unmount();
      app = null;
    }
    if (appRoot) {
      appRoot.remove();
      appRoot = null;
    }
    const frameEl = window.frameElement as HTMLIFrameElement | null;
    if (frameEl) {
      frameEl.style.display = 'none';
    }
  } catch (error) {
    console.error('[快捷指令面板] 清理失败', error);
  }
}

$(window).on('pagehide', () => {
  cleanup();
});
