import type {
  RawData,
  ExportData,
  ImportSelection,
  ImportMode,
  PrefixSuffixItem
} from '../types';

/**
 * 执行合并（根据模式分发）
 */
export function executeMerge(
  current: RawData,
  imported: ExportData,
  mode: ImportMode,
  selection: ImportSelection
): RawData {
  switch (mode) {
    case 'overwrite':
      return overwriteMerge(current, imported, selection);
    case 'merge':
      return smartMerge(current, imported, selection);
    case 'append':
      return appendMerge(current, imported, selection);
    default:
      throw new Error(`未知的导入模式: ${mode}`);
  }
}

/**
 * 完全覆盖模式
 */
export function overwriteMerge(
  current: RawData,
  imported: ExportData,
  selection: ImportSelection
): RawData {
  const result = { ...current };

  if (selection.data && imported.data) {
    result.data = imported.data;
  }

  if (selection.prefix && imported.prefix) {
    result.prefix = imported.prefix;
    result.perfix = imported.prefix;
  }

  if (selection.suffix && imported.suffix) {
    result.suffix = imported.suffix;
  }

  return result;
}

/**
 * 完全追加模式
 */
export function appendMerge(
  current: RawData,
  imported: ExportData,
  selection: ImportSelection
): RawData {
  const result = { ...current };

  if (selection.data && imported.data) {
    result.data = [...current.data, ...imported.data];
  }

  if (selection.prefix && imported.prefix) {
    const currentPrefix = current.prefix ?? current.perfix ?? [];
    result.prefix = [...currentPrefix, ...imported.prefix];
    result.perfix = result.prefix;
  }

  if (selection.suffix && imported.suffix) {
    const currentSuffix = current.suffix ?? [];
    result.suffix = [...currentSuffix, ...imported.suffix];
  }

  return result;
}

/**
 * 智能合并模式
 */
export function smartMerge(
  current: RawData,
  imported: ExportData,
  selection: ImportSelection
): RawData {
  const result = { ...current };

  if (selection.data && imported.data) {
    result.data = mergeDataArray(current.data, imported.data);
  }

  if (selection.prefix && imported.prefix) {
    const currentPrefix = current.prefix ?? current.perfix ?? [];
    result.prefix = mergePrefixSuffix(currentPrefix, imported.prefix);
    result.perfix = result.prefix;
  }

  if (selection.suffix && imported.suffix) {
    const currentSuffix = current.suffix ?? [];
    result.suffix = mergePrefixSuffix(currentSuffix, imported.suffix);
  }

  return result;
}

/**
 * 合并主数据数组（递归合并同名条目）
 */
function mergeDataArray(current: unknown[], imported: unknown[]): unknown[] {
  const result = [...current];
  const nameMap = buildNameMap(current);

  for (const item of imported) {
    mergeNamedItem(result, nameMap, item);
  }

  return result;
}

/**
 * 构建名称到索引的映射
 */
function buildNameMap(data: unknown[]): Map<string, number> {
  const map = new Map<string, number>();

  data.forEach((item, index) => {
    const name = extractItemName(item);
    if (name) map.set(name, index);
  });

  return map;
}

/**
 * 提取条目名称
 */
function extractItemName(item: unknown): string | null {
  if (typeof item === 'string') return item;
  if (Array.isArray(item) && typeof item[0] === 'string') return item[0];
  if (isPlainObject(item)) {
    const keys = Object.keys(item);
    return keys.length > 0 ? keys[0] : null;
  }
  return null;
}

/**
 * 合并单个条目
 */
function mergeItem(current: unknown, imported: unknown): unknown {
  if (Array.isArray(current) && Array.isArray(imported)) {
    return mergeArrayItem(current, imported);
  }

  if (isPlainObject(current) && isPlainObject(imported)) {
    return mergeObjectItem(current, imported);
  }

  return imported;
}

/**
 * 合并数组类型的条目
 */
function mergeArrayItem(current: unknown[], imported: unknown[]): unknown[] {
  if (current.length === 0) return imported;
  if (imported.length === 0) return current;

  if (!isNamedArrayItem(current) && !isNamedArrayItem(imported)) {
    return mergeDataArray(current, imported);
  }

  const result = [...current];
  if (Array.isArray(current[1]) && Array.isArray(imported[1])) {
    result[1] = mergeSecondLevelList(current[1], imported[1]);
  } else {
    result[1] = imported[1] ?? current[1];
  }

  return result;
}

/**
 * 判断数组是否为命名条目元组
 */
function isNamedArrayItem(item: unknown[]): boolean {
  return typeof item[0] === 'string';
}

/**
 * 合并对象类型的条目
 */
function mergeObjectItem(
  current: Record<string, unknown>,
  imported: Record<string, unknown>
): Record<string, unknown> {
  const result = { ...current };

  for (const [key, value] of Object.entries(imported)) {
    if (key in result) {
      result[key] = mergeItem(result[key], value);
    } else {
      result[key] = value;
    }
  }

  return result;
}

/**
 * 合并前缀/后缀列表（以键名去重）
 */
function mergePrefixSuffix(
  current: PrefixSuffixItem[],
  imported: PrefixSuffixItem[]
): PrefixSuffixItem[] {
  const result = [...current];
  const keyMap = buildPrefixSuffixMap(current);

  for (const item of imported) {
    const key = Object.keys(item)[0];
    const existingIndex = keyMap.get(key);
    if (existingIndex === undefined) {
      keyMap.set(key, result.length);
      result.push(item);
    } else {
      result[existingIndex] = item;
    }
  }

  return result;
}

/**
 * 构建前缀后缀键名索引
 */
function buildPrefixSuffixMap(data: PrefixSuffixItem[]): Map<string, number> {
  const map = new Map<string, number>();

  data.forEach((item, index) => {
    const key = Object.keys(item)[0];
    if (key) map.set(key, index);
  });

  return map;
}

/**
 * 合并具名列表项
 */
function mergeNamedItem(result: unknown[], nameMap: Map<string, number>, item: unknown): void {
  const name = extractItemName(item);
  if (!name) {
    result.push(item);
    return;
  }

  const existingIndex = nameMap.get(name);
  if (existingIndex !== undefined) {
    result[existingIndex] = mergeItem(result[existingIndex], item);
    return;
  }

  nameMap.set(name, result.length);
  result.push(item);
}

/**
 * 合并数组项的二级列表
 */
function mergeSecondLevelList(current: unknown[], imported: unknown[]): unknown[] {
  const nameMap = buildNameMap(current);
  const result = [...current];

  for (const item of imported) {
    mergeNamedItem(result, nameMap, item);
  }

  return result;
}

/**
 * 判断是否为普通对象
 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}
