import { ref, watch, type Ref, type ComputedRef } from 'vue';
import type { SelectedGridItem, PrefixSuffixItem } from '../types';
import { escapeForRegExp } from '../utils/util';

interface UseMacroSubstitutionOptions {
  replaceNames: ComputedRef<{ user?: string[]; char?: string[] } | undefined>;
  selectedGridItems: Ref<SelectedGridItem[]>;
  prefixList: ComputedRef<PrefixSuffixItem[]>;
  suffixList: ComputedRef<PrefixSuffixItem[]>;
  selectedPrefixIndexes: Ref<Set<number>>;
  selectedSuffixIndexes: Ref<Set<number>>;
  fixedPrefix: Ref<string>;
  fixedSuffix: Ref<string>;
  userName: () => string;
  charName: () => string;
}

/**
 * Macro 替换 composable
 *
 * 管理文本替换逻辑、替换开关、文本同步
 */
export function useMacroSubstitution(options: UseMacroSubstitutionOptions) {
  const {
    replaceNames,
    selectedGridItems,
    prefixList,
    suffixList,
    selectedPrefixIndexes,
    selectedSuffixIndexes,
    fixedPrefix,
    fixedSuffix,
    userName,
    charName,
  } = options;

  // 从 localStorage 恢复替换开关
  const restoreReplaceNames = () => {
    try {
      const stored = localStorage.getItem('quicksend:lastReplaceNames');
      if (stored) {
        const saved = JSON.parse(stored);
        return {
          user: saved.user ?? false,
          char: saved.char ?? false,
        };
      }
    } catch (e) {
      // ignore
    }
    return { user: false, char: false };
  };

  const lastReplaceNames = restoreReplaceNames();
  const replaceUserNames = ref(lastReplaceNames.user);
  const replaceCharNames = ref(lastReplaceNames.char);
  const swapUserCharNames = ref(false);

  const text = ref('');
  const originalText = ref('');
  const tavernText = ref('');

  /**
   * 获取前缀/后缀项的值
   */
  function getPrefixSuffixValue(item: any): string {
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      const keys = Object.keys(item);
      if (keys.length > 0) {
        const value = item[keys[0]];
        return typeof value === 'string' ? value : String(value);
      }
    }
    return '';
  }

  /**
   * 将一组别名替换为目标名称
   */
  function replaceAliasGroup(input: string, raws: string[], target: string): string {
    let processed = input;
    new Set(raws).forEach(raw => {
      if (!raw) return;
      const pattern = escapeForRegExp(raw);
      processed = processed.replace(new RegExp(pattern, 'gi'), target);
    });
    return processed;
  }

  /**
   * 获取用于识别 user / char 的全部词项
   *
   * 包含实际名字与用户配置的替换词，供互换按钮独立查找使用。
   */
  function getSearchTerms(type: 'user' | 'char'): string[] {
    const name = type === 'user' ? userName() : charName();
    const aliases = ((type === 'user' ? replaceNames.value?.user : replaceNames.value?.char) as string[] | undefined) ?? [];
    return Array.from(new Set([name, ...aliases].map(item => item.trim()).filter(Boolean))).sort((a, b) => b.length - a.length);
  }

  /**
   * 构建词项所属索引
   */
  function createTermOwnerMap(userTerms: string[], charTerms: string[]): Map<string, 'user' | 'char'> {
    const termOwnerMap = new Map<string, 'user' | 'char'>();
    userTerms.forEach(term => termOwnerMap.set(term.toLocaleLowerCase(), 'user'));
    charTerms.forEach(term => {
      const key = term.toLocaleLowerCase();
      if (!termOwnerMap.has(key)) termOwnerMap.set(key, 'char');
    });
    return termOwnerMap;
  }

  /**
   * 扫描文本中的 user / char 命中片段
   */
  function collectSwapMatches(input: string, userTerms: string[], charTerms: string[]) {
    const pattern = [...userTerms, ...charTerms].map(escapeForRegExp).join('|');
    if (!pattern) return [];
    const termOwnerMap = createTermOwnerMap(userTerms, charTerms);
    return Array.from(input.matchAll(new RegExp(pattern, 'gi')))
      .map(match => {
        const text = match[0];
        const start = match.index ?? 0;
        return { text, start, end: start + text.length, owner: termOwnerMap.get(text.toLocaleLowerCase()) };
      })
      .filter(item => item.owner != null);
  }

  /**
   * 按组交换命中的 user / char 文本
   */
  function swapMatchedTextGroups(input: string, matches: Array<{ text: string; start: number; end: number; owner?: 'user' | 'char' }>): string {
    const userText = matches.find(item => item.owner === 'user')?.text;
    const charText = matches.find(item => item.owner === 'char')?.text;
    if (!userText || !charText) return input;

    let output = '';
    let cursor = 0;
    matches.forEach(item => {
      output += input.slice(cursor, item.start);
      output += item.owner === 'user' ? charText : userText;
      cursor = item.end;
    });
    return `${output}${input.slice(cursor)}`;
  }

  /**
   * 对文本执行一次 user / char 互换
   *
   * 该逻辑不依赖勾选开关，只依赖名字与替换词配置。
   */
  function swapUserCharInText(input: string): string {
    if (!swapUserCharNames.value) return input;
    const userTerms = getSearchTerms('user');
    const charTerms = getSearchTerms('char');
    const matches = collectSwapMatches(input, userTerms, charTerms);
    if (matches.length === 0) return input;
    return swapMatchedTextGroups(input, matches);
  }

  /**
   * 应用 Macro 替换到文本
   */
  function applyMacroToText(input: string): string {
    let processed = input;

    // 替换 {{user}}
    if (replaceUserNames.value && userName() && replaceNames.value?.user) {
      processed = replaceAliasGroup(processed, replaceNames.value.user as string[], userName());
    }

    // 替换 {{char}}
    if (replaceCharNames.value && charName() && replaceNames.value?.char) {
      processed = replaceAliasGroup(processed, replaceNames.value.char as string[], charName());
    }

    return swapUserCharInText(processed);
  }

  /**
   * 构建选中的前缀/后缀拼接文本
   */
  function buildSelectedConcat(list: PrefixSuffixItem[], selected: Set<number>): string {
    let out = '';
    list.forEach((item, idx) => {
      if (selected.has(idx)) {
        const v = getPrefixSuffixValue(item);
        if (v) out += v;
      }
    });
    return out;
  }

  /**
   * 应用 Macro 替换到完整文本
   */
  function applyMacroSubstitution() {
    // 对原始文本应用宏替换
    const processedText = applyMacroToText(originalText.value);

    // 构建前后缀
    const prefixConcatRaw = buildSelectedConcat(prefixList.value, selectedPrefixIndexes.value);
    const suffixConcatRaw = buildSelectedConcat(suffixList.value, selectedSuffixIndexes.value);
    const fixedPreRaw = fixedPrefix.value || '';
    const fixedSufRaw = fixedSuffix.value || '';

    // 对前后缀和固定前后缀也应用宏替换
    const fixedPre = applyMacroToText(fixedPreRaw);
    const prefixConcat = applyMacroToText(prefixConcatRaw);
    const suffixConcat = applyMacroToText(suffixConcatRaw);
    const fixedSuf = applyMacroToText(fixedSufRaw);

    // 拼接处理后的文本（固定前后缀需要出现在最外层）
    const mainText = `${fixedPre}${prefixConcat}${processedText}${suffixConcat}${fixedSuf}`;

    // 最后追加酒馆文本（不应用宏替换）
    text.value = tavernText.value ? `${mainText}\n\n${tavernText.value}` : mainText;
  }

  /**
   * 同步选中 Grid 项的文本
   */
  function syncSelectedGridText() {
    originalText.value = selectedGridItems.value.map(item => item.value).join('');
  }

  /**
   * 追加 SillyTavern 文本
   */
  function appendSillyTavernText() {
    try {
      // 快捷指令面板在 iframe 中运行，需要访问父页面的输入框
      const textarea = window.parent.document.querySelector('#send_textarea') as HTMLTextAreaElement;
      if (textarea) {
        tavernText.value = textarea.value;
      }
    } catch (e) {
      // 跨域或其他错误时静默失败
      console.warn('[快捷指令面板] 无法访问 ST 输入框:', e);
    }
    applyMacroSubstitution();
  }

  // watch 自动触发
  watch(
    selectedGridItems,
    () => {
      syncSelectedGridText();
    },
    { deep: true },
  );

  watch(originalText, () => {
    applyMacroSubstitution();
  });

  watch([replaceUserNames, replaceCharNames, swapUserCharNames], () => {
    applyMacroSubstitution();

    // 持久化到 localStorage
    try {
      localStorage.setItem(
        'quicksend:lastReplaceNames',
        JSON.stringify({
          user: replaceUserNames.value,
          char: replaceCharNames.value,
        }),
      );
    } catch (e) {
      // ignore
    }
  });

  watch(
    [selectedPrefixIndexes, selectedSuffixIndexes],
    () => {
      applyMacroSubstitution();
    },
    { deep: true },
  );

  watch([fixedPrefix, fixedSuffix], () => {
    applyMacroSubstitution();
  });

  return {
    replaceUserNames,
    replaceCharNames,
    swapUserCharNames,
    text,
    originalText,
    tavernText,
    applyMacroSubstitution,
    syncSelectedGridText,
    appendSillyTavernText,
  };
}
