import { ref, watch, type Ref } from 'vue';

type SelectionMode = 'ordered-list' | 'single' | 'multi-set';

interface BaseOptions<M extends SelectionMode> {
  mode: M;
}

interface PersistConfig<T> {
  key: string;
  serialize: (val: T) => any;
  deserialize: (val: any) => T;
}

interface OrderedListOptions extends BaseOptions<'ordered-list'> {
  persist?: PersistConfig<any[]>;
}

interface SingleOptions extends BaseOptions<'single'> {
  persist?: PersistConfig<number | null>;
}

interface MultiSetOptions extends BaseOptions<'multi-set'> {
  persist?: PersistConfig<Set<number>>;
}

type UseSelectionModelOptions =
  | OrderedListOptions
  | SingleOptions
  | MultiSetOptions;

interface OrderedListModel {
  selected: Ref<any[]>;
  toggle: (item: any) => void;
  clear: () => void;
  isSelected: (item: any) => boolean;
  remove: (item: any) => void;
}

interface SingleModel {
  selected: Ref<number | null>;
  toggle: (_item: any, idx: number) => void;
  clear: () => void;
  isSelected: (_item: any, idx: number) => boolean;
  remove: () => void;
}

interface MultiSetModel {
  selected: Ref<Set<number>>;
  toggle: (_item: any, idx: number) => void;
  clear: () => void;
  isSelected: (_item: any, idx: number) => boolean;
  remove: (_item: any, idx: number) => void;
}

export function useSelectionModel(options: OrderedListOptions): OrderedListModel;
export function useSelectionModel(options: SingleOptions): SingleModel;
export function useSelectionModel(options: MultiSetOptions): MultiSetModel;
export function useSelectionModel(options: UseSelectionModelOptions): OrderedListModel | SingleModel | MultiSetModel {
  const { mode } = options;
  const persist = options.persist as PersistConfig<any> | undefined;

  /**
   * 获取默认值
   */
  function getDefaultValue(mode: SelectionMode): any {
    if (mode === 'ordered-list') return [];
    if (mode === 'single') return null;
    return new Set();
  }

  // 初始化状态
  let selected: Ref<any>;

  if (persist) {
    try {
      const stored = localStorage.getItem(persist.key);
      const initial = stored ? persist.deserialize(JSON.parse(stored)) : getDefaultValue(mode);
      selected = ref(initial);
    } catch (e) {
      selected = ref(getDefaultValue(mode));
    }

    watch(
      selected,
      val => {
        try {
          const serialized = persist.serialize(val);
          localStorage.setItem(persist.key, JSON.stringify(serialized));
        } catch (e) {
          // ignore
        }
      },
      { deep: true },
    );
  } else {
    selected = ref(getDefaultValue(mode));
  }

  // 根据模式实现方法
  if (mode === 'ordered-list') {
    return createOrderedListModel(selected as Ref<any[]>);
  } else if (mode === 'single') {
    return createSingleModel(selected as Ref<number | null>);
  } else {
    return createMultiSetModel(selected as Ref<Set<number>>);
  }
}

/**
 * 创建有序列表模型（Grid 选中列表）
 */
function createOrderedListModel(selected: Ref<any[]>) {
  return {
    selected,
    /**
     * 切换选中状态
     */
    toggle(item: any) {
      const idx = selected.value.findIndex(it => it.id === item.id);
      if (idx >= 0) {
        selected.value.splice(idx, 1);
      } else {
        selected.value.push(item);
      }
    },
    /**
     * 清空选中
     */
    clear() {
      selected.value = [];
    },
    /**
     * 判断是否选中
     */
    isSelected(item: any) {
      return selected.value.some(it => it.id === item.id);
    },
    /**
     * 移除选中项
     */
    remove(item: any) {
      selected.value = selected.value.filter(it => it.id !== item.id);
    },
  };
}

/**
 * 创建单选模型（Grid 高亮单选）
 */
function createSingleModel(selected: Ref<number | null>) {
  return {
    selected,
    /**
     * 切换选中状态
     */
    toggle(_item: any, idx: number) {
      selected.value = idx;
    },
    /**
     * 清空选中
     */
    clear() {
      selected.value = null;
    },
    /**
     * 判断是否选中
     */
    isSelected(_item: any, idx: number) {
      return selected.value === idx;
    },
    /**
     * 移除选中项
     */
    remove() {
      selected.value = null;
    },
  };
}

/**
 * 创建多选集合模型（前后缀多选）
 */
function createMultiSetModel(selected: Ref<Set<number>>) {
  return {
    selected,
    /**
     * 切换选中状态
     */
    toggle(_item: any, idx: number) {
      if (selected.value.has(idx)) {
        selected.value.delete(idx);
      } else {
        selected.value.add(idx);
      }
      selected.value = new Set(selected.value); // 触发响应式
    },
    /**
     * 清空选中
     */
    clear() {
      selected.value = new Set();
    },
    /**
     * 判断是否选中
     */
    isSelected(_item: any, idx: number) {
      return selected.value.has(idx);
    },
    /**
     * 移除选中项
     */
    remove(_item: any, idx: number) {
      selected.value.delete(idx);
      selected.value = new Set(selected.value);
    },
  };
}
